{"type": "tool_started", "tool_name": "write_file", "tool_input": {"path": "output/filtered_query.sparql", "content": "PREFIX : <http://www.example.org/product-review#>

SELECT ?reviewId ?reviewTitle ?reviewText ?reviewDate ?productName WHERE {
  ?review a :Review ;
          :forProduct ?product ;
          :reviewId ?reviewId ;
          :reviewTitle ?reviewTitle ;
          :reviewText ?reviewText ;
          :reviewDate ?reviewDate ;
          :reviewerName ?reviewerName .
  ?product a :Product ;
           :productName ?productName .
  FILTER(CONTAINS(?productName, "iPhone"))
  FILTER(?rating > 3.5)
}
ORDER BY DESC(?rating)"}}

